// src/pages/CreatePollPage.js
import React, { useEffect, useState } from "react";
import { createPoll } from "../services/pollService";
import "../styles/CreatePoll.css";

export default function CreatePollPage({ currentUser }) {
  const [question, setQuestion] = useState("");
  const [choices, setChoices] = useState(["", ""]);
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState("");
  const [message, setMessage] = useState("");
  const token = localStorage.getItem("token");

  useEffect(() => {
    // завантажимо канали для вибору
    fetch("http://127.0.0.1:8000/api/channels/", {
      headers: {
        "Content-Type": "application/json",
        ...(token && { Authorization: `Bearer ${token}` }),
      },
    })
      .then(res => res.json())
      .then(data => setChannels(Array.isArray(data) ? data : data.results || []))
      .catch(() => setChannels([]));
  }, [token]);

  if (!currentUser || !currentUser.is_staff) {
    return <p>Доступ заборонено — лише адміністратори можуть створювати опитування.</p>;
  }

  const handleChoiceChange = (idx, val) => {
    const arr = [...choices];
    arr[idx] = val;
    setChoices(arr);
  };

  const addChoice = () => setChoices(prev => [...prev, ""]);

  const removeChoice = (idx) => {
    if (choices.length <= 2) return; // мінімум 2 варіанти
    setChoices(prev => prev.filter((_, i) => i !== idx));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");

    const filtered = choices.map(c => (c || "").trim()).filter(Boolean);
    if (!question.trim()) {
      setMessage("Введіть питання.");
      return;
    }
    if (filtered.length < 2) {
      setMessage("Потрібно щонайменше 2 варіанти відповіді.");
      return;
    }
    if (!selectedChannel) {
      setMessage("Оберіть канал.");
      return;
    }

    try {
      await createPoll({ question: question.trim(), channelId: parseInt(selectedChannel), choices: filtered }, token);
      setMessage("✅ Опитування створено!");
      setQuestion("");
      setChoices(["", ""]);
      setSelectedChannel("");
    } catch (err) {
      console.error(err);
      setMessage("❌ Помилка: " + (err.message || "невідома"));
    }
  };

  return (
    <div className="create-poll-page">
      <h2>Створити опитування</h2>
      <form onSubmit={handleSubmit} className="create-poll-form">
        <label>Питання</label>
        <input value={question} onChange={(e) => setQuestion(e.target.value)} />

        <label>Канал</label>
        <select value={selectedChannel} onChange={e => setSelectedChannel(e.target.value)} required>
          <option value="">-- Оберіть канал --</option>
          {channels.map(ch => <option key={ch.id} value={ch.id}>{ch.name}</option>)}
        </select>

        <label>Варіанти відповіді</label>
        {choices.map((c, i) => (
          <div key={i} className="choice-row">
            <input
              value={c}
              onChange={(e) => handleChoiceChange(i, e.target.value)}
              placeholder={`Варіант ${i+1}`}
            />
            <button type="button" onClick={() => removeChoice(i)} disabled={choices.length <= 2}>✖</button>
          </div>
        ))}

        <button type="button" onClick={addChoice}>Додати варіант</button>

        <div className="actions">
          <button type="submit">Створити опитування</button>
        </div>

        {message && <p className="message">{message}</p>}
      </form>
    </div>
  );
}
